// Combine context from similar messages and knowledge base
const query = $input.first().json.body.message;
const tenantId = $input.first().json.body.tenant_id;
const embedding = $('Generate Query Embedding').first().json.embedding;

// Get similar messages context
const similarMessages = $('Search Similar Messages').all().map(item => ({
  content: item.json.content,
  role: item.json.role,
  similarity: item.json.similarity_score
}));

// Get knowledge base context
const knowledgeBase = $('Search Knowledge Base').all().map(item => ({
  title: item.json.title,
  content: item.json.content,
  category: item.json.category,
  similarity: item.json.similarity_score
}));

// Build context for AI
let context = "Relevant conversation history:\n";
similarMessages.forEach(msg => {
  context += `- ${msg.role}: ${msg.content} (similarity: ${msg.similarity.toFixed(2)})\n`;
});

context += "\nRelevant knowledge base articles:\n";
knowledgeBase.forEach(kb => {
  context += `- ${kb.title} (${kb.category}): ${kb.content} (similarity: ${kb.similarity.toFixed(2)})\n`;
});

return {
  json: {
    query: query,
    context: context,
    tenant_id: tenantId,
    embedding: embedding,
    similar_messages_count: similarMessages.length,
    knowledge_articles_count: knowledgeBase.length
  }
};
